content:
@import "tailwindcss";

:root {
  --bg: #09090b;
  --panel: #111113;
  --line: #27272a;
  --accent: #f97316;
}

html {
  scroll-behavior: smooth;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
}

/* visible keyboard focus on the dark theme (orange, offset ring) */
:focus-visible {
  outline: 2px solid rgba(249, 115, 22, 0.8);
  outline-offset: 2px;
}

body {
  background: var(--bg);
  color: #e4e4e7;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

::selection {
  background: rgba(249, 115, 22, 0.35);
}

/* subtle grid backdrop for the hero */
.hero-grid {
  background-image:
    linear-gradient(rgba(63, 63, 70, 0.25) 1px, transparent 1px),
    linear-gradient(90deg, rgba(63, 63, 70, 0.25) 1px, transparent 1px);
  background-size: 44px 44px;
  -webkit-mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, black 40%, transparent 100%);
  mask-image: radial-gradient(ellipse 80% 60% at 50% 0%, black 40%, transparent 100%);
}

.glow {
  background: radial-gradient(closest-side, rgba(249, 115, 22, 0.16), transparent);
}

pre, code, .mono {
  font-family: ui-monospace, "SF Mono", Menlo, Consolas, "Liberation Mono", monospace;
}

.pretty-scroll::-webkit-scrollbar { width: 8px; height: 8px }
.pretty-scroll::-webkit-scrollbar-thumb { background: #3f3f46; border-radius: 4px }
.pretty-scroll::-webkit-scrollbar-track { background: transparent }
